301	    /** A mutable variable declared at the top level of a component.  Like
302	     * StaticBinding it lives in the singleton field of its own inner class,
303	     * but that field holds a MutableFValue cell rather than the value, so that
304	     * reads and writes can go through the current transaction exactly as
305	     * LocalMutableVar and MutableTaskVarCodeGen do, and so that a nested
306	     * code-generation context captures the cell rather than a copy of the
307	     * value.  A separate class rather than a flag on StaticBinding, so that
308	     * assignment to an immutable top-level variable keeps failing.
309	     */
310	    public static class MutableStaticBinding extends NeedsType {
311	
312	        /** Internal name of the variable's declared type, for the cast after
313	         *  reading the cell. */
314	        private final String typeInternalName;
315	
316	        public MutableStaticBinding(IdOrOp id, Type fortressType, String owner, String name,
317	                                    String typeInternalName) {
318	            super(id, fortressType, owner, name, NamingCzar.descFortressMutableFValueInternal);
319	            this.typeInternalName = typeInternalName;
320	        }
