326	        public void pushValue(CodeGenMethodVisitor mv) {
327	            Label atomicEnd = new Label();
328	            Label end = new Label();
329	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
330	                               "com/sun/fortress/runtimeSystem/BaseTask",
331	                               "inATransaction",
332	                               "()Z");
333	            mv.visitJumpInsn(Opcodes.IFEQ, atomicEnd);
334	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
335	                               "com/sun/fortress/runtimeSystem/BaseTask",
336	                               "getCurrentTransaction",
337	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
338	            pushCell(mv);
339	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
340	                               "com/sun/fortress/runtimeSystem/Transaction",
341	                               "TXRead",
342	                               "(" + NamingCzar.descFortressMutableFValueInternal + ")" + NamingCzar.descFortressAny);
343	            mv.visitJumpInsn(Opcodes.GOTO, end);
344	            mv.visitLabel(atomicEnd);
345	
346	            pushCell(mv);
347	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
348	                               "com/sun/fortress/compiler/runtimeValues/MutableFValue",
349	                               "getValue",
350	                               "()" + NamingCzar.descFortressAny);
351	            mv.visitLabel(end);
352	            InstantiatingClassloader.generalizedCastTo(mv, typeInternalName);
353	        }
