366	                               "com/sun/fortress/runtimeSystem/BaseTask",
367	                               "getCurrentTransaction",
368	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
369	            mv.visitInsn(Opcodes.SWAP);
370	            pushCell(mv);
371	            mv.visitInsn(Opcodes.SWAP);
372	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
373	                               "com/sun/fortress/runtimeSystem/Transaction",
